class Solution {
public:
    int numIdenticalPairs(vector<int>& a) {
        unordered_map<int, int> cnt;
        int ans = 0;
        for (int x : a) ans += cnt[x]++;    // add pairs with earlier copies, then count this one
        return ans;
    }
};
